package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Attribute_getValue_TriageGen1Test {

    @Test
    public void testGetValue_withNormalValue() {
        String key = "href";
        String value = "https://example.com";
        Attribute attribute = new Attribute(key, value);

        assertEquals(value, attribute.getValue());
    }

    @Test
    public void testGetValue_withEmptyValue() {
        String key = "class";
        String value = "";
        Attribute attribute = new Attribute(key, value);

        assertEquals("", attribute.getValue());
    }

    @Test
    public void testGetValue_withNullValue() {
        String key = "data-test";
        String value = null;
        Attribute attribute = new Attribute(key, value);

        assertNull(value);
        assertEquals(null, attribute.getValue());
    }

    @Test
    public void testGetValue_afterSetValue() {
        Attribute attribute = new Attribute("id", "old-id");
        String newValue = "new-id";
        attribute.setValue(newValue);

        assertEquals(newValue, attribute.getValue());
    }

    @Test
    public void testGetValue_withSpecialCharacters() {
        String key = "alt";
        String value = "Text with <brackets> & \"quotes\"";
        Attribute attribute = new Attribute(key, value);

        assertEquals(value, attribute.getValue());
    }

    @Test
    public void testGetValue_fromCreateFromEncoded() {
        // Testing the static factory method to ensure the value is retrieved correctly
        // Note: createFromEncoded behavior depends on implementation of decoding
        String key = "title";
        String encodedValue = "hello%20world"; 
        // Assuming createFromEncoded decodes, but even if it doesn't, 
        // we test that getValue returns the value state.
        Attribute attribute = Attribute.createFromEncoded(key, encodedValue);

        assertNotNull(attribute.getValue());
    }
}
